---@alias gcp.apigee_v1.GoogleCloudApigeeV1RatePlanRevenueShareTypeEnum "REVENUE_SHARE_TYPE_UNSPECIFIED"|"FIXED"|"VOLUME_BANDED"

---@alias gcp.apigee_v1.GoogleCloudApigeeV1RatePlanStateEnum "STATE_UNSPECIFIED"|"DRAFT"|"PUBLISHED"

